// Material and attack-role detail is baked into the existing model atlas, never per frame.
function line(c,p,color,w=1.4){c.beginPath();c.moveTo(...p[0]);for(let i=1;i<p.length;i++)c.lineTo(...p[i]);c.strokeStyle=color;c.lineWidth=w;c.lineJoin='round';c.stroke()}
function poly(c,p,fill,stroke='#26342f'){c.beginPath();c.moveTo(...p[0]);for(let i=1;i<p.length;i++)c.lineTo(...p[i]);c.closePath();c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke()}}
function oval(c,x,y,rx,ry,color,stroke){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke()}}
function rivets(c,points,color='#c6c3a0'){for(const [x,y]of points)oval(c,x,y,1,1,color)}
export function shadeModel(c,kind){if(!c.createRadialGradient)return;const dimensions={brute:[0,-14,20,23],warden:[0,-18,21,29],spitter:[0,-10,23,19],dragon:[0,-13,18,28],broodmother:[0,-18,21,25],charger:[0,-8,25,16],ravager:[0,-8,25,16],wolf:[0,-8,23,12],mage:[0,-10,17,27],healer:[0,-10,17,27],tank:[0,-13,18,25]},[x,y,rx,ry]=dimensions[kind]||[0,-15,13,23],gradient=c.createRadialGradient(x-rx*.4,y-ry*.35,1,x,y,Math.max(rx,ry));if(!gradient?.addColorStop)return;gradient.addColorStop(0,'#fff0c744');gradient.addColorStop(.5,'#ffffff00');gradient.addColorStop(1,'#07172077');c.save();c.globalCompositeOperation='source-atop';c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=gradient;c.fill();c.restore()}
export function paintEnemyDetails(c,kind,color,frame){
 if(kind==='walker'||kind==='ranger'){
  poly(c,[[-10,-23],[-2,-20],[-4,-13],[-12,-16]],'#69736b');line(c,[[-10,-20],[-5,-18]],'#b6bd9b');poly(c,[[3,-10],[9,-7],[8,0],[3,-2]],'#5c493c');line(c,[[-7,-5],[6,-4]],'#a48b65',2);rivets(c,[[-10,-20],[-5,-18],[6,-5]]);line(c,[[-4,-32],[-1,-33],[3,-32]],'#b9b49b',1);line(c,[[3,-38],[0,-34],[2,-31]],'#69796b',1);
  if(kind==='walker'){poly(c,[[-7,-38],[-6,-42],[2,-43],[6,-39],[5,-37]],'#718078');line(c,[[-5,-40],[3,-40]],'#a2aca0');poly(c,[[14,-9],[20,-29],[23,-34],[24,-24],[18,-7]],'#a7aa94');line(c,[[13,-8],[21,-6]],'#8f7151',2);line(c,[[15,-4],[19,-15]],'#9a8059',2)}
  else{poly(c,[[-20,-25],[-14,-28],[-9,-5],[-15,-3]],'#79604b');for(let i=0;i<3;i++){line(c,[[-18+i*2,-23],[-22+i*2,-41]],'#c3b28c');poly(c,[[-23+i*2,-43],[-19+i*2,-39],[-23+i*2,-38]],'#c6c0a6',null)}line(c,[[14,-15],[19,-14]],'#dfb994',3);line(c,[[14,-18],[17,-17]],'#816d51',2)}
 }else if(kind==='bat'){for(const d of [-1,1]){line(c,[[d*5,-12],[d*14,-21],[d*24,-14]],'#b9a1bf88');line(c,[[d*6,-10],[d*17,-12],[d*23,-3]],'#c8aabd66');poly(c,[[d*2,-10],[d*3,-5],[d*5,-10]],'#ede4ca',null);line(c,[[d*3,-1],[d*6,4],[d*8,1]],'#b7b1a2',1);oval(c,d*2,-17,1,1,'#ffb38c')}}
 else if(kind==='brute'){for(const d of [-1,1]){poly(c,[[d*11,-29],[d*23,-30],[d*28,-18],[d*15,-15]],'#737b75');poly(c,[[d*12,-27],[d*22,-27],[d*24,-22],[d*14,-20]],'#9ba59b');rivets(c,[[d*14,-25],[d*22,-24]]);line(c,[[d*12,-8],[d*23,-4]],'#756952',3)}poly(c,[[-12,-18],[0,-22],[13,-18],[11,-3],[0,2],[-10,-4]],'#58685d');line(c,[[-6,-17],[3,-4],[7,-13]],'#b9ad7c',2);line(c,[[-11,-28],[9,-30]],'#527153',2);poly(c,[[19,1],[30,-17],[37,-15],[24,5]],'#74634f');for(let i=0;i<3;i++)line(c,[[28+i*2,-15+i*3],[34+i*2,-13+i*3]],'#a2a18c',2);line(c,[[-4,-40],[0,-37],[3,-39]],'#c5c7a2');}
 else if(kind==='charger'||kind==='ravager'){const wild=kind==='ravager';for(let i=0;i<4;i++)poly(c,[[-13+i*8,-22],[-9+i*8,-27],[-3+i*8,-21],[-5+i*8,-12],[-12+i*8,-12]],wild?'#8b5848':'#758077');for(let i=0;i<5;i++)line(c,[[-15+i*7,-19],[-11+i*7,-15]],'#c3b298',1);for(const d of [-1,1]){poly(c,[[20,-23+d*3],[27,-34+d*2],[32,-32+d*3],[26,-20+d*3]],'#d7c6a4');line(c,[[-13+d*5,10],[-10+d*5,14]],'#cabdab',2)}if(wild){for(let i=0;i<6;i++)poly(c,[[5+i*2,-20],[3+i*2,-32-i%2*4],[9+i*2,-23]],'#9e6b4d');line(c,[[23,-17],[28,-16]],'#f7ba8a',2)}else{poly(c,[[20,-25],[29,-24],[31,-17],[22,-14]],'#8c9a93');rivets(c,[[24,-22],[28,-19]])}}
 else if(kind==='spitter'){for(let i=0;i<8;i++){const x=-16+i*4,y=-12-(i%3)*4;oval(c,x,y,2.5,2,'#516d3e');oval(c,x-.7,y-.7,1,1,'#c6d87f')}oval(c,0,-6,12,7,'#bad477','#517144');line(c,[[-9,-4],[-4,-1],[4,-2],[10,-6]],'#d7e598',1);for(const d of [-1,1]){oval(c,d*19,-4,4,6,'#aac36a','#526b40');line(c,[[d*16,-1],[d*22,8]],'#9da887');poly(c,[[d*4,-8],[d*5,-3],[d*7,-8]],'#dbe4b2',null)}line(c,[[7,-7],[11,0],[9,6]],'#a5d576',1.5)}
 else if(kind==='shaman'||kind==='hexer'){const hex=kind==='hexer';poly(c,[[-12,-23],[-17,-16],[-14,-3],[-9,-10],[-3,-18]],hex?'#76618f':'#716e53');for(let i=0;i<3;i++){poly(c,[[-11+i*5,-18],[-8+i*5,-23],[-5+i*5,-18],[-8+i*5,-12]],hex?'#ba9cda':'#d6cda0');line(c,[[-8+i*5,-19],[-8+i*5,-14]],'#3a4140',1)}poly(c,[[-20,-2],[-23,-14],[-11,-16],[-8,-5]],hex?'#866e9e':'#8d7653');line(c,[[-21,-12],[-12,-13]],'#e1d2a2');line(c,[[-20,-8],[-11,-9]],hex?'#e0b7fa':'#b6c88c');poly(c,[[-10,-36],[-13,-48],[-7,-45],[-1,-55],[4,-45],[11,-49],[9,-36]],hex?'#9674b2':'#b6b08c');for(const x of [-5,3])oval(c,x,-42,1,1,hex?'#f0beff':'#293e33');line(c,[[18,-34],[23,-28],[16,-20],[20,-13]],hex?'#d6b2ec':'#e2d6aa',1.5);rivets(c,[[-14,-11],[-11,-7]]);if(!hex){poly(c,[[-8,-36],[-7,-44],[0,-47],[8,-41],[7,-31],[2,-28],[-5,-30]],'#d1c5a0');for(const x of [-3,4])oval(c,x,-38,2,2.5,'#263c32');line(c,[[-3,-32],[4,-32]],'#887e60');for(const d of [-1,1])line(c,[[d*7,-44],[d*14,-51],[d*15,-58]],'#d1c5a0',2.5)}else{poly(c,[[-10,-35],[-6,-42],[0,-43],[7,-40],[9,-33],[5,-29],[-5,-29]],'#5e426f');line(c,[[-4,-36],[4,-36]],'#f3bfed',1.3);poly(c,[[-4,-31],[0,-29],[4,-31],[0,-26]],'#ba9dc6')}}
 else if(kind==='wraith'||kind==='frostking'){const frost=kind==='frostking';for(const d of [-1,1]){line(c,[[d*8,-20],[d*15,-8],[d*10,3]],frost?'#d5f6f3':'#b3c7c7',1.5);for(let i=0;i<3;i++)poly(c,[[d*(8+i*4),-4+i*3],[d*(12+i*3),13+i*2],[d*(4+i*4),5+i*3]],frost?'#7fb7c1':'#587e81');line(c,[[d*16,-8],[d*22,0],[d*20,4]],'#aaa991',1)}poly(c,[[-5,-20],[0,-26],[6,-19],[0,-9]],frost?'#d6ffff':'#8bbab6');poly(c,[[-2,-19],[0,-22],[2,-19],[0,-14]],frost?'#79d6e5':'#d7f0d2',null);if(frost){for(let i=0;i<5;i++)poly(c,[[-12+i*5,-37],[-11+i*5,-51-i%2*6],[-7+i*5,-37]],'#a7dfe7');line(c,[[-11,-35],[11,-35]],'#e4ffff',2);for(const d of [-1,1])poly(c,[[d*16,-22],[d*22,-36],[d*28,-20],[d*21,-11]],'#9bcdd6')}else{for(let i=0;i<4;i++)line(c,[[-13+i*8,3],[-15+i*8,10]],'#b5c2ac',1)}}
 else if(kind==='broodmother'){for(let i=0;i<5;i++){const y=-35+i*7;line(c,[[-12,y],[-3,y+4],[5,y+3],[13,y-1]],'#c5b78d88',1.3)}poly(c,[[-7,-30],[0,-35],[8,-30],[0,-16]],'#b17e68');for(const d of [-1,1]){for(let i=0;i<4;i++){oval(c,d*(5+i%2*4),-7+i*3,1.5,1.5,i%2?'#f3d093':'#e79c7e');line(c,[[d*(16+i*2),-24+i*7],[d*(26+i),-26+i*7]],'#c8b28f',1)}oval(c,d*9,-20,4,6,'#d1bc8d66');poly(c,[[d*6,7],[d*10,17],[d*2,11]],'#e1cc9e')}}
 else if(kind==='warden'){for(let i=0;i<5;i++){const y=-30+i*7;line(c,[[-14,y],[-2,y+3],[11,y-1]],'#b5baa155',1.3)}for(const d of [-1,1]){poly(c,[[d*13,-30],[d*29,-25],[d*30,-16],[d*19,-13]],'#a6b39e');line(c,[[d*18,-25],[d*25,-22],[d*22,-17]],'#526f61',2);oval(c,d*11,-14,3,2,'#78915b');rivets(c,[[d*21,-24],[d*26,-19]])}poly(c,[[-9,-45],[-4,-54],[2,-50],[7,-53],[12,-43]],'#91a08a');line(c,[[-3,-27],[2,-21],[-2,-14],[3,-7]],'#e2f0a2',1.5);line(c,[[-8,6],[-3,9],[5,8]],'#a2aa8f',2)}
 else if(kind==='dragon'){for(let row=0;row<4;row++)for(let i=0;i<3;i++){const x=-8+i*7+(row%2)*2,y=-26+row*8;poly(c,[[x-3,y],[x,y+4],[x+3,y],[x,y-2]],row%2?'#bd9060':'#946447','#79513d')}for(const d of [-1,1]){line(c,[[d*11,-23],[d*25,-38],[d*38,-33]],'#e1ac7a',1);line(c,[[d*18,-16],[d*28,-29],[d*40,-26]],'#c9946a88',1);poly(c,[[17+d*3,-43],[14+d*5,-57],[23+d*4,-45]],'#d8c49e');line(c,[[d*11,12],[d*18,15]],'#e1d2ac',2)}poly(c,[[26,-35],[34,-36],[36,-32],[28,-30]],'#e9af6a');line(c,[[28,-33],[35,-32]],'#f8d99a',1.2);oval(c,26,-40,1,2,'#273933')}
 else if(['wolf','firepet','frostpet','stormpet'].includes(kind)){if(kind==='wolf'){for(let i=0;i<5;i++)line(c,[[-12+i*6,-18],[-8+i*6,-13]],'#e0e0c9',1);line(c,[[18,-18],[22,-17]],'#596954');poly(c,[[26,-8],[28,-3],[30,-8]],'#e9e5ce',null)}else if(kind==='firepet'){for(let i=0;i<4;i++)poly(c,[[-4+i*3,-15],[-2+i*3,-11],[i*3,-16]],'#d9b378')}else if(kind==='frostpet'){for(const d of [-1,1])for(let i=0;i<3;i++)line(c,[[d*8,-12],[d*(17+i*3),-14+i*3]],'#d6eeeb',1)}else{line(c,[[-2,-25],[3,-20],[-1,-15],[4,-10]],'#c09b53',1.3)}}
}
